content.solution_code:
class Spell {
  constructor(name, manaCost) {
    this.name = name;
    this.manaCost = manaCost;
  }

  cast() {
    return `${this.name} spell prepared, costing ${this.manaCost} mana.`;
  }
}

class Fireball extends Spell {
  constructor(name, manaCost, damage) {
    super(name, manaCost);
    this.damage = damage;
  }

  cast() {
    return `${this.name} spell launched! It deals ${this.damage} damage and costs ${this.manaCost} mana.`;
  }
}

class IceShard extends Spell {
  constructor(name, manaCost, freezeDuration) {
    super(name, manaCost);
    this.freezeDuration = freezeDuration;
  }

  cast() {
    return `${this.name} spell cast! It freezes target for ${this.freezeDuration} seconds and costs ${this.manaCost} mana.`;
  }
}

